import { test, expect } from '@playwright/test';

const BASE_URL = process.env.TARGET_URL || 'https://adactinhotelapp.com/';
const USERNAME = process.env.TARGET_USERNAME || 'ADACTINFORQA';
const PASSWORD = process.env.TARGET_PASSWORD || '3U0515';

test('Search with past check-in date', async ({ page }) => {
  // Navigate to base URL
  console.log('[Timeline] Navigate to Adactin Hotel App');
  await page.goto(BASE_URL);

  // Login
  console.log('[Timeline] Login: enter username');
  await page.locator('input#username').fill(USERNAME);
  console.log('[Timeline] Login: enter password');
  await page.locator('input#password').fill(PASSWORD);
  console.log('[Timeline] Login: click Login button');
  await page.locator('input#login').click();

  // Wait for redirect to Search Hotel page
  console.log('[Timeline] Wait for redirect to SearchHotel.php');
  await expect(page).toHaveURL(/SearchHotel\.php/);

  // Step 1: Clear the Check In Date field
  console.log('[Timeline] Clear default check-in date');
  await page.locator('input#datepick_in').fill('');

  // Step 2: Enter a past date
  console.log('[Timeline] Enter past check-in date: 01/01/2020');
  await page.locator('input#datepick_in').fill('01/01/2020');

  // Step 3: Fill other mandatory fields
  console.log('[Timeline] Select Location: Sydney');
  await page.locator('select#location').selectOption({ label: 'Sydney' });

  console.log('[Timeline] Select Number of Rooms: 1 - One');
  await page.locator('select#room_nos').selectOption({ label: '1 - One' });

  console.log('[Timeline] Enter Check Out Date: 05/01/2020');
  await page.locator('input#datepick_out').fill('05/01/2020');

  console.log('[Timeline] Select Adults per Room: 1');
  await page.locator('select#adult_room').selectOption({ label: '1' });

  // Step 4: Click Search button
  console.log('[Timeline] Click Search button');
  await page.locator('input#Submit').click();

  // Assert: The form does not submit and the user remains on the Search Hotel page
  console.log('[Timeline] Assert that user remains on SearchHotel.php');
  await expect(page).toHaveURL(/SearchHotel\.php/);
  // Also verify that the search form is still present (e.g., location dropdown visible)
  await expect(page.locator('select#location')).toBeVisible();
});
